-- ============================================================================
-- V2026_09_14_03: FULL re-seed of interchange_rate_local for BOTH tenants
-- (AE country + AE tenant-1 + BH country), domestic + international, aligned
-- to the Mastercard MEA interchange manual (Sep-2026 edition, user-supplied).
--
-- Fixes baked into this snapshot (vs the previous seeds):
--  A. AE country-level generic debit/prepaid rows converged to the MC manual
--     (debit POS 0.75% cap AED 37.50, prepaid POS 1.00% cap 50, ECOM 1.00%
--     cap 50) - they previously kept pre-Aug-2026 caps (137.63/183.50) and
--     only the tenant-1 overrides were correct.
--  B. AE MCC-band debit/prepaid caps were 3.67x too high (old seed converted
--     USD->AED; the manual states the caps in AED directly):
--     91.75 -> 25.00, 119.28 -> 32.50, 3.67 -> 1.00. 108 rows.
--  C. NEW AE MC credit Elite tier rows at 2.125% (midpoint of manual World
--     EE 2.10% / World Elite EE 2.15%, pending a BIN-weight query). INERT
--     until UAE tenant sets tenant.card_type_source='BIN' (FILE-sourced
--     tiering resolves only Standard/Premium).
--  D. AE MC REX (Real Estate) ticket split was INVERTED vs the manual:
--     now <3670 AED (USD 1,000) -> 1.20%, >=3670 -> 0.65%, POS+ECOM.
--  BH rows are unchanged (they matched the manual) and re-inserted verbatim.
--
-- NOT changed (flagged, needs business sign-off - may be Visa/CB-sourced):
--  - AE priority-20 any-scheme sector rows (Govt 0.35 / Edu 0.30 / RE 0.30 /
--    Trans 0.45) vs MC manual 0.50/0.65/1.20-0.65/0.50.
--  - AE exchange-house 1.16% vs manual USD 0.50 flat <=USD1k then 1.20-1.30%
--    (credit) / AED 2.00 flat (debit).
--  - INTERNATIONAL 1.85% flat placeholder rows (all schemes except BH Benefit).
--
-- Row order matters: ties at equal priority resolve by id ASC, so the INSERTs
-- below preserve the original id order per country.
--
-- GUARDED one-time flip (migration ledger convention): DELETE + every INSERT
-- run only while this file's schema_migration_log row is absent - a re-run
-- never wipes later manual edits. Splitter-safe (no $$). Apply once via psql
-- on UAT/prod, then rebuild-summaries with reprice:true for AE periods
-- (fixes B and D restate historical fees).
-- ============================================================================

DELETE FROM interchange_rate_local
WHERE country_code IN ('AE','BH')
  AND NOT EXISTS (SELECT 1 FROM schema_migration_log
                  WHERE filename = 'V2026_09_14_03__interchange_full_reseed_mc_manual_align.sql');


-- Verify: expect AE country 385, AE tenant-1 375, BH country 935; no stale caps left
SELECT country_code, COALESCE(CAST(tenant_id AS VARCHAR),'country') AS scope, COUNT(*)
FROM interchange_rate_local WHERE country_code IN ('AE','BH')
GROUP BY country_code, tenant_id ORDER BY country_code, tenant_id NULLS FIRST;
SELECT COUNT(*) AS old_caps_left FROM interchange_rate_local
WHERE country_code='AE' AND cap_amount IN (91.75, 119.28, 3.67);

